    const c = cs[i]
    const sl = line, sc = col
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') { adv(); continue }
    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      adv(); adv()
      let depth = 1
      while (i < n && depth > 0) {
        if (cs[i] === '/' && cs[i + 1] === '*') { adv(); adv(); depth++ }
        else if (cs[i] === '*' && cs[i + 1] === '/') { adv(); adv(); depth-- }
        else adv()
      }
      if (depth > 0) throw new ScanError(sl, sc, 'unterminated block comment')
      continue
    }
    if (isLetter(c) || c === '_') {
      if (c === 'r' && cs[i + 1] === '"') {
        adv(); adv()
        let v = ''
        while (i < n && cs[i] !== '"') v += adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        adv()
        tokens.push({ line: sl, col: sc, kind: 'rawstring', body: JSON.stringify(v) })
        continue
      }
      let s = ''
      while (i < n && isIdentChar(cs[i])) s += adv()
      tokens.push({ line: sl, col: sc, kind: KEYWORDS.has(s) ? 'keyword' : 'ident', body: s })
      continue
    }
    if (isDigit(c)) {
      let s = ''
      let bad = false
      const take = () => { s += adv() }
      // digit run with single underscores between digits
      const run = (ok) => {
        let any = false
        while (i < n) {
          if (ok(cs[i])) { take(); any = true }
          else if (cs[i] === '_' && any && ok(cs[i + 1])) take()
          else break
        }
        return any
      }
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        take(); take()
        const lc = p.toLowerCase()
        const ok = lc === 'x' ? isHex : lc === 'b' ? (d) => d === '0' || d === '1' : (d) => d !== undefined && d >= '0' && d <= '7'
        if (!run(ok)) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) { take(); run(isDigit) }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1]) || ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2]))) {
            take()
            if (!isDigit(cs[i])) take()
            run(isDigit)
          }
        }
      }
      if (bad || isIdentChar(cs[i])) {
        while (i < n && isIdentChar(cs[i])) take()
        throw new ScanError(sl, sc, `invalid number ${s}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'number', body: s })
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const d = cs[i]
        if (d === '"') { adv(); break }
        if (d === '\n') throw new ScanError(line, col, 'newline in string')
        if (d !== '\\') { v += adv(); continue }
        const bl = line, bc = col
        adv()
        if (i >= n) throw new ScanError(sl, sc, 'unterminated string')
        const e = adv()
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.prototype.hasOwnProperty.call(simple, e)) v += simple[e]
        else if (e === 'x') {
          if (isHex(cs[i]) && isHex(cs[i + 1])) {
            v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16)); adv(); adv()
          } else throw new ScanError(bl, bc, 'invalid escape \\x')
        } else if (e === 'u') {
          let j = i
          let h = ''
          if (cs[j] === '{') {
            j++
            while (isHex(cs[j])) h += cs[j++]
            if (cs[j] === '}' && h.length > 0 && parseInt(h, 16) <= 0x10ffff) {
              v += String.fromCodePoint(parseInt(h, 16))
              while (i <= j) adv()
              continue
            }
          }
          throw new ScanError(bl, bc, 'invalid escape \\u')
        } else throw new ScanError(bl, bc, `invalid escape \\${e}`)
      }
      tokens.push({ line: sl, col: sc, kind: 'string', body: JSON.stringify(v) })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT.includes(two)) { adv(); adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: two }); continue }
    if (PUNCT1.has(c)) { adv(); tokens.push({ line: sl, col: sc, kind: 'punct', body: c }); continue }
    throw new ScanError(sl, sc, `unexpected character ${c}`)
  }
  return tokens
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'tokens' && mode[0] !== 'stats')) {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
let tokens
try {
  tokens = scan(readFileSync(0).toString('utf8'))
} catch (e) {
  if (!(e instanceof ScanError)) throw e
  process.stderr.write(`error: ${e.line}:${e.col}: ${e.message}\n`)
  process.exit(2)
}
let out = ''
if (mode[0] === 'tokens') {
  for (const t of tokens) out += `${t.line}:${t.col} ${t.kind} ${t.body}\n`
} else {
  for (const k of KINDS) out += `${k} ${tokens.filter((t) => t.kind === k).length}\n`
  out += `total ${tokens.length}\n`
}
